import {distance,move,xyz,geography,clamp} from './planet.js';
import {hash} from './genetics.js';

// Chord-space buckets work across the longitude seam and at both poles.
export class Neighborhood {
 constructor(items,size=4){this.size=size;this.buckets=new Map();for(const p of items){const v=xyz(p.x,p.z),k=[v.x,v.y,v.z].map(n=>Math.floor(n/size)).join(',');if(!this.buckets.has(k))this.buckets.set(k,[]);this.buckets.get(k).push(p);}}
 near(p,r){const v=xyz(p.x,p.z),s=this.size,out=[];for(let x=Math.floor((v.x-r)/s);x<=Math.floor((v.x+r)/s);x++)for(let y=Math.floor((v.y-r)/s);y<=Math.floor((v.y+r)/s);y++)for(let z=Math.floor((v.z-r)/s);z<=Math.floor((v.z+r)/s);z++)for(const q of this.buckets.get(`${x},${y},${z}`)||[])if(distance(p,q)<=r)out.push(q);return out;}
}
export function plantGenome(seed,parent=null,random=null){const sample=i=>hash(Math.floor(seed*1000)+i*7919)/4294967296;const mutate=v=>clamp(v+(random()-.5)*.12,.15,1);return parent?{nectar:mutate(parent.nectar),height:mutate(parent.height),dispersal:mutate(parent.dispersal),generation:parent.generation+1}:{nectar:.25+sample(1)*.65,height:.2+sample(2)*.75,dispersal:.2+sample(3)*.7,generation:1};}
export function inheritKnowledge(c,mother,father){c.mind.knowledge??=[];if(c.mind.knowledgeInherited)return;for(const p of [mother,father])for(const k of p?.mind?.knowledge?.slice(0,3)||[])if(!c.mind.knowledge.some(o=>o.id===k.id))c.mind.knowledge.push({...k,strength:k.strength*.65,source:p.id});if(mother||father)c.mind.knowledgeInherited=true;}
export class Lifeways {
 constructor(sim,saved){this.sim=sim;this.clock=saved?.clock??0;this.plantCursor=saved?.plantCursor??0;this.censusClock=saved?.censusClock??0;this.traditions=saved?.traditions??[];this.lost=saved?.lost??[];this.totals={transmissions:0,forgotten:0,care:0,companionship:0,pollinations:0,dispersed:0,germinated:0,refuge:0,...saved?.totals};this.noticeAt=saved?.noticeAt??{};for(const c of sim.creatures)this.ensure(c);for(const f of sim.food)this.ensurePlant(f);this.index();}
 ensure(c){c.social??={bonds:{},intent:null,nextAt:0,careGiven:0,careReceived:0};c.ecology??={pollen:null,seeds:[],visits:0,dispersed:0};c.social.nearIds??=[];inheritKnowledge(c);return c.social;}
 ensurePlant(f){f.genes??=plantGenome(f.seed);f.pollinated??=false;f.nectar??=.4;f.reproductionAt??=this.sim.time+15;return f;}
 index(){this.animals=new Neighborhood(this.sim.creatures);this.plants=new Neighborhood(this.sim.food);}
 snapshot(){return{clock:this.clock,plantCursor:this.plantCursor,censusClock:this.censusClock,traditions:this.traditions,lost:this.lost,totals:this.totals,noticeAt:this.noticeAt};}
 notice(key,text,icon,kind,c){if(this.sim.time<(this.noticeAt[key]??0))return;this.noticeAt[key]=this.sim.time+50;this.sim.log(text,icon,kind,c?.id,c);}
 practice(c,action,value,type){if(value<=0)return;this.ensure(c);const ks=c.mind.knowledge;let k=ks.find(k=>k.action===action&&k.type===type);if(!k){k={id:`${c.id}:${action}:${type??'none'}`,action,type,origin:c.region,founder:c.id,source:c.id,strength:.35};ks.push(k);}k.strength=clamp(k.strength+.12,0,1);k.used=this.sim.time;c.mind.knowledge=ks.sort((a,b)=>b.strength-a.strength).slice(0,8);}
 copy(from,to){this.ensure(from);this.ensure(to);const k=from.mind.knowledge.slice().sort((a,b)=>b.strength-a.strength)[0];if(!k||k.strength<.18)return;let own=to.mind.knowledge.find(o=>o.id===k.id);if(own)own.strength=clamp(own.strength+k.strength*.15,0,1);else if(to.mind.knowledge.length<8){own={...k,strength:k.strength*(.65+this.sim.random()*.2),source:from.id};to.mind.knowledge.push(own);}else return;this.totals.transmissions++;this.bond(from,to,.07);}
 bias(c,action){return(c.mind.knowledge||[]).filter(k=>k.action===action).reduce((a,k)=>Math.max(a,k.strength*.22),0);}
 bond(a,b,amount){if(!a||!b||a===b)return;this.ensure(a);this.ensure(b);for(const [p,q] of [[a,b],[b,a]]){const bonds=p.social.bonds;bonds[q.id]=clamp((bonds[q.id]||0)+amount,-1,1);const entries=Object.entries(bonds).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])).slice(0,8);p.social.bonds=Object.fromEntries(entries);}}
 born(child,mother,father){this.ensure(child);this.bond(child,mother,.9);if(this.sim.byId.has(father?.id))this.bond(child,father,.65);}
 related(a,b){return a.mother===b.id||a.father===b.id||b.mother===a.id||b.father===a.id||(a.mother&&a.mother===b.mother);}
 choose(c){const so=this.ensure(c),sim=this.sim;if(c.recovery?.mode!=='active'||c.stage||c.mind.job||c.energy<55||so.nextAt>sim.time||c.state==='Huyendo')return false;const peers=so.nearIds.map(id=>sim.byId.get(id)).filter(p=>p&&p!==c&&distance(c,p)<=6&&p.species===c.species&&!p.stage);const kin=peers.filter(p=>this.related(c,p)),young=kin.filter(p=>p.age<3&&c.age>=3).sort((a,b)=>a.energy-b.energy)[0];let target,kind;
 if(young&&c.energy>78){target=young;kind=young.energy<70?'care':'wait';}
 else if(c.age<3){target=kin.filter(p=>p.age>=3).sort((a,b)=>distance(c,a)-distance(c,b))[0];kind='follow';}
 else if(c.energy>88&&sim.random()<c.dna.traits.sociality*.35){target=peers.filter(p=>(so.bonds[p.id]||0)>.16).sort((a,b)=>(so.bonds[b.id]||0)-(so.bonds[a.id]||0))[0];kind='company';}
 if(!target)return false;so.intent={id:target.id,kind,until:sim.time+6};so.nextAt=sim.time+12;c.think=6;this.guide(c);return true;}
 guide(c){const intent=c.social?.intent;if(!intent)return false;const p=this.sim.byId.get(intent.id);if(!p||intent.until<=this.sim.time||c.energy<45||c.stage||c.state==='Huyendo'){c.social.intent=null;if(c.state!=='Huyendo'){c.target=null;c.think=0;}return false;}const d=distance(c,p);c.state={care:'Cuidando',wait:'Esperando a su cría',follow:'Siguiendo a su familia',company:'Acompañando'}[intent.kind];c.target=d>1.3?{x:p.x,z:p.z,kind:'social',id:p.id}:null;if(d<1.8){c.heading=Math.atan2(moveBearing(c,p).x,moveBearing(c,p).z);if(intent.kind==='care'&&!intent.fed&&c.energy>65&&p.energy<80){const amount=Math.min(8,p.age<3?80-p.energy:4,c.energy-65);c.energy-=amount;p.energy+=amount;c.social.careGiven++;p.social.careReceived++;this.totals.care++;this.bond(c,p,.12);this.copy(c,p);intent.fed=true;this.notice('care',c.name+' alimenta a '+p.name+'.','♡','social',c);}else if(!intent.met){intent.met=true;this.bond(c,p,.04);this.totals.companionship++;}}return true;}
 consume(c,f){this.ensure(c);this.ensurePlant(f);if(f.type===1&&!f.pollinated)return;if(c.ecology.seeds.length<3)c.ecology.seeds.push({type:f.type,genes:this.seedGenes(f),x:f.x,z:f.z,at:this.sim.time+10+f.genes.dispersal*20});}
 seedGenes(f){const g={...f.genes};if(f.pollenGenes)for(const key of ['nectar','height','dispersal'])g[key]=(g[key]+f.pollenGenes[key])/2;return g;}
 germinate(p,type,genes,parent){if(this.sim.recovery)return this.sim.recovery.propagate(p,type,genes,parent);if(this.sim.food.length>=this.sim.foodCapacity||this.sim.local(p).moisture<.18)return null;const water=geography(p.x,p.z).water;if((type===4)!==water)return null;const f=this.sim.addFood(p,.03,type);if(!f||f.type!==type)return null;f.genes=plantGenome(f.seed,genes,()=>this.sim.random());f.parentPlant=parent??null;this.ensurePlant(f);this.totals.germinated++;return f;}
 visit(c,f){this.ensure(c);this.ensurePlant(f);if(c.recovery?.mode==='dormant'||f.recovery?.dormant||f.type!==1||f.growth<.6||f.nectar<.06||c.species===3||c.species===5)return false;const access=clamp(1-Math.abs(c.dna.traits.neck*.5-f.genes.height),.15,1),food=Math.min(f.nectar,access*.15);f.nectar-=food;c.energy=clamp(c.energy+food*3,0,100);const pollen=c.ecology.pollen;if(pollen&&pollen.id!==f.id&&pollen.until>this.sim.time&&!f.pollinated){f.pollinated=true;f.pollenGenes={...pollen.genes};this.totals.pollinations++;this.notice('pollination',c.name+' lleva polen entre flores solares.','✿','ecology',c);}c.ecology.pollen={id:f.id,genes:{...f.genes},until:this.sim.time+35};c.ecology.visits++;c.ecology.glowUntil=this.sim.time+3;return true;}
 shelter(c){if(c.species===3)return 0;return Math.min(.65,this.plants.near(c,1.6).reduce((n,f)=>n+((f.type===2||f.type===4)&&!f.recovery?.dormant&&f.growth>.6?.14*f.growth:0),0)/Math.max(.6,c.dna.traits.size));}
 tick(dt){this.clock+=dt;if(this.clock<2)return;const elapsed=this.clock;this.clock=0;this.index();const sim=this.sim;
 for(const c of sim.creatures){const so=this.ensure(c);for(const [id,strength] of Object.entries(so.bonds)){if(!sim.byId.has(+id))delete so.bonds[id];else{so.bonds[id]=strength*Math.exp(-elapsed/600);if(Math.abs(so.bonds[id])<.025)delete so.bonds[id];}}const nearby=this.animals.near(c,6).filter(p=>p!==c).sort((a,b)=>distance(c,a)-distance(c,b)).slice(0,24);so.nearIds=nearby.map(p=>p.id);for(const p of nearby)if(p.id>c.id&&p.species===c.species&&distance(c,p)<2.5)this.bond(c,p,.007*c.dna.traits.sociality);
 const m=c.mind;for(const k of m.knowledge)k.strength*=Math.exp(-elapsed/(210+210*c.dna.traits.cognition));const before=m.knowledge.length;m.knowledge=m.knowledge.filter(k=>k.strength>.10);this.totals.forgotten+=before-m.knowledge.length;for(const key in m.q)m.q[key]*=Math.exp(-elapsed/600);m.practice.materials=m.practice.materials.map(v=>v*Math.exp(-elapsed/500));m.practice.routes=m.practice.routes.map(r=>({...r,value:r.value*Math.exp(-elapsed/400)})).filter(r=>r.value>.015);m.trust=Object.fromEntries(Object.entries(m.trust).filter(([id,v])=>sim.byId.has(+id)&&Math.abs(v)>.03).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])).slice(0,12).map(([id,v])=>[id,v*Math.exp(-elapsed/500)]));
 if(c.species!==3){const flowers=this.plants.near(c,1.3).filter(f=>f.type===1&&f.growth>.6);if(flowers.length)this.visit(c,flowers.sort((a,b)=>distance(c,a)-distance(c,b))[0]);}c.ecology.cover=this.shelter(c);
 for(let i=c.ecology.seeds.length-1;i>=0;i--){const seed=c.ecology.seeds[i];if(seed.at>sim.time)continue;c.ecology.seeds.splice(i,1);if(distance(c,seed)<2)continue;this.totals.dispersed++;c.ecology.dispersed++;const offspring=this.germinate(c,seed.type,seed.genes);if(offspring){sim.deposit(c.x,c.z,.12,'Semilla dispersada');this.notice('seed',c.name+(offspring.dormant?' deja semillas a la espera de mejores condiciones.':' deja semillas que brotan lejos de su origen.'),'♧','ecology',c);}}
 }
 // A rotating, bounded reproductive budget; no scan of every plant against every animal.
 const count=Math.min(80,sim.food.length);for(let i=0;i<count;i++){const f=sim.food[this.plantCursor++%sim.food.length];this.ensurePlant(f);const elapsedPlant=Math.min(180,sim.time-(f.ecologyAt??sim.time));f.ecologyAt=sim.time;if(f.type===1){const recharge=Math.min(.8-f.nectar,elapsedPlant*.006*sim.local(f).light*f.genes.nectar,f.biomass*.03);f.nectar+=Math.max(0,recharge);f.biomass-=Math.max(0,recharge)*.08;}if(f.recovery?.dormant||f.growth<.8||f.reproductionAt>sim.time)continue;f.reproductionAt=sim.time+35;if(f.type===1&&!f.pollinated)continue;const mix=this.seedGenes(f);const a=sim.random()*Math.PI*2,r=1+f.genes.dispersal*3,p=move(f.x,f.z,Math.sin(a)*r,Math.cos(a)*r);if(this.germinate(p,f.type,mix,f.id)){f.biomass=Math.max(.1,f.biomass-.15);f.pollinated=false;}}
 this.censusClock+=elapsed;if(this.censusClock>=12){this.censusClock=0;this.census();}
 }
 census(){const living=new Map();for(const c of this.sim.creatures)for(const k of c.mind.knowledge){let t=living.get(k.id);if(!t){t={...k,holders:0,regions:[]};living.set(k.id,t);}t.holders++;if(!t.regions.includes(c.region))t.regions.push(c.region);}for(const old of this.traditions)if(!living.has(old.id)&&old.holders>=2){this.lost.unshift({...old,lostAt:this.sim.time});this.notice('lost','Una práctica compartida perdió a sus últimos conocedores.','◇','culture');}this.lost=this.lost.slice(0,24);this.traditions=[...living.values()].sort((a,b)=>b.holders-a.holders).slice(0,96);}
}
function moveBearing(a,b){const v1=xyz(a.x,a.z),v2=xyz(b.x,b.z),lon=a.x/42,lat=a.z/42;return{x:(v2.x-v1.x)*Math.cos(lon)-(v2.z-v1.z)*Math.sin(lon),z:-(v2.x-v1.x)*Math.sin(lat)*Math.sin(lon)+(v2.y-v1.y)*Math.cos(lat)-(v2.z-v1.z)*Math.sin(lat)*Math.cos(lon)};}
